static unsigned char *read_file(const char *zPath, size_t *pn){
FILE *f = fopen(zPath, "rb");
unsigned char *a;
long n;
if( f==0 ) return 0;
fseek(f, 0, SEEK_END);
n = ftell(f);
fseek(f, 0, SEEK_SET);
a = (unsigned char*)malloc((size_t)n);
if( a==0 ){
fclose(f);
return 0;
}
if( fread(a, 1, (size_t)n, f)!=(size_t)n ){
free(a);
fclose(f);
return 0;
}
fclose(f);
*pn = (size_t)n;
return a;
}

static int find_bytes(const unsigned char *a, size_t n, const char *z){
size_t m = strlen(z);
size_t i;
if( m==0 || m>n ) return 0;
for(i=0; i+m<=n; i++){
if( memcmp(&a[i], z, m)==0 ) return 1;
}
return 0;
}

static void scan_central_names(const unsigned char *a, size_t n){
size_t i = 0;
