if( find_bytes(&a[i+46], nName, "new-entry.txt") ){
printf(" contains-new-entry");
}
if( find_bytes(&a[i+46], nName, "VIRTUAL TABLE") ){
printf(" contains-sql-text");
}
}
printf("\n");
i += 46 + nName + nExtra + nComment;
}else{
i++;
}
}
}

