INSERT INTO t1 VALUES('hello','world');

-- Baseline (no index, no aiMap reordering): correct.
SELECT (NULL,'WORLD') IN     (SELECT a,b FROM t1);    -- expect 0
SELECT (NULL,'WORLD') NOT IN (SELECT a,b FROM t1);    -- expect 1

-- With index on (b,a) the planner uses it for the IN operator. The
-- LHS register order becomes (b,a) while the collation lookup in step 6
-- still walks (a,b). Both queries return NULL.
CREATE INDEX i1 ON t1(b,a);
SELECT (NULL,'WORLD') IN     (SELECT a,b FROM t1);    -- BUG: returns NULL
SELECT (NULL,'WORLD') NOT IN (SELECT a,b FROM t1);    -- BUG: returns NULL

