CREATE VIRTUAL TABLE t USING fts5(x, content='', contentless_delete=1);
INSERT INTO t(rowid,x) VALUES(1,'a b'),(2,'c d'),(3,'e f'),(4,'g h'),(5,'i j');
INSERT INTO t(t) VALUES('optimize');
