-o sqlite3_oom -lm

vuln_001_mock_oom.c:
#include "sqlite3.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static const sqlite3_mem_methods *gReal;
static sqlite3_int64 gMin, gMax;
static void *mock_malloc(int n){
if( n>=gMin && n<=gMax ){
fprintf(stderr, "[mock_oom] failing malloc(%d)\n", n);
return 0;
}
return gReal->xMalloc(n);
}
static void mock_free(void *p){ gReal->xFree(p); }
static void *mock_realloc(void *p, int n){ return gReal->xRealloc(p, n); }
static int  mock_size(void *p){ return gReal->xSize(p); }
static int  mock_roundup(int n){ return gReal->xRoundup(n); }
static int  mock_init(void *p){ return gReal->xInit(p); }
static void mock_shutdown(void *p){ gReal->xShutdown(p); }
static sqlite3_mem_methods gMock = {
mock_malloc, mock_free, mock_realloc, mock_size, mock_roundup,
mock_init, mock_shutdown, 0
};
int mock_extra_init(const char *unused){
static sqlite3_mem_methods real;
sqlite3_config(SQLITE_CONFIG_GETMALLOC, &real);
gReal = &real;
const char *lo = getenv("OOM_FAIL_MIN"), *hi = getenv("OOM_FAIL_MAX");
gMin = lo ? atoll(lo) : (1LL<<60);
gMax = hi ? atoll(hi) : (1LL<<60);
sqlite3_config(SQLITE_CONFIG_MALLOC, &gMock);
return SQLITE_OK;
}

