if( g_skip>0 ){ fprintf(stderr,"[mock_oom] skip malloc(%d)\n",n); g_skip--; }
else          { fprintf(stderr,"[mock_oom] fail malloc(%d)\n",n); return 0; }
}
return g_real.xMalloc(n);
}
static void  oF(void*p){ g_real.xFree(p); }
static void *oR(void*p,int n){
