#include <string.h>
#include "sqlite3.h"
#include "fts5.h"

static int synCreate(void *c, const char **az, int n, fts5_tokenizer **ppOut) {
(void)c; (void)az; (void)n;
extern fts5_tokenizer synModule;
fts5_tokenizer *p = sqlite3_malloc(sizeof *p);
if (!p) return SQLITE_NOMEM;
*p = synModule; *ppOut = p; return SQLITE_OK;
}
static void synDelete(fts5_tokenizer *p) { sqlite3_free(p); }
static int synTokenize(fts5_tokenizer *t, void *ctx, int fl,
const char *pText, int nText,
int (*xToken)(void*,int,const char*,int,int,int))
{
(void)t; (void)fl;
int i = 0, rc = SQLITE_OK;
while (i < nText && rc == SQLITE_OK) {
while (i < nText && pText[i]==' ') i++;
int s = i;
while (i < nText && pText[i]!=' ') i++;
if (i==s) break;
rc = xToken(ctx, 0, pText+s, i-s, s, i);
/* "usa" -> colocated synonym "united" */
if (rc==SQLITE_OK && i-s==3 &&
pText[s]=='u' && pText[s+1]=='s' && pText[s+2]=='a') {
int r = xToken(ctx, FTS5_TOKEN_COLOCATED, "united", 6, s, i);
if (r!=SQLITE_OK && r!=SQLITE_DONE) rc = r;
}
}
return rc;
}
fts5_tokenizer synModule = { synCreate, synDelete, synTokenize };

static fts5_api *getFts5Api(sqlite3 *db) {
fts5_api *p = 0; sqlite3_stmt *s = 0;
if (SQLITE_OK==sqlite3_prepare(db,"SELECT fts5(?1)",-1,&s,0)) {
sqlite3_bind_pointer(s, 1, &p, "fts5_api_ptr", 0);
sqlite3_step(s);
