}
static void exec(sqlite3 *db, const char *sql) {
char *err=0; sqlite3_exec(db,sql,0,0,&err); sqlite3_free(err);
}
static int countRows(sqlite3 *db, const char *sql) {
sqlite3_stmt *s=0; int n=0;
sqlite3_prepare_v2(db,sql,-1,&s,0);
while (sqlite3_step(s)==SQLITE_ROW) {
printf("    matched: %s\n", sqlite3_column_text(s,0)); n++;
}
sqlite3_finalize(s); return n;
}

