Summary
A NULL pointer dereference vulnerability exists in the sha1_query() SQL function implemented in ext/misc/sha1.c (also compiled into the CLI via src/shell.c.in). When the query passed to sha1_query() returns a zero-length BLOB column (e.g., zeroblob(0) or X''), sqlite3_column_blob() returns a NULL pointer per SQLite API contract, but sha1QueryFunc() passes this NULL pointer to hash_step() without checking for NULL. The hash_step() function then calls memcpy(dst, NULL, 0), which is undefined behavior per the C standard (C11 §7.24.1). On UBSan/hardened builds this causes an abort (DoS); on normal builds it is undefined behavior that could crash on platforms with guard pages or strict memcpy implementations.

The single-value sha1() function correctly checks for NULL (if( pData==0 ) return;) before calling hash_step(), but sha1_query() lacks this check — a classic "function returns NULL.

Vulnerable Code/* ext/misc/sha1.c:375-387 — sha1QueryFunc, SQLITE_BLOB case */
case SQLITE_BLOB: {
int n2 = sqlite3_column_bytes(pStmt, i);
const unsigned char *z2 = sqlite3_column_blob(pStmt, i);
/* BUG: z2 can be NULL for zero-length BLOBs; no NULL check */
hash_step_vformat(&cx,"B%d:",n2);
hash_step(&cx, z2, n2);    /* NULL dereference: memcpy(dst, NULL, 0) */
break;
}

/* ext/misc/sha1.c:375-380 — sha1QueryFunc, SQLITE_TEXT case */
case SQLITE_TEXT: {
int n2 = sqlite3_column_bytes(pStmt, i);
const unsigned char *z2 = sqlite3_column_text(pStmt, i);
/* NOTE: sqlite3_column_text() for empty TEXT returns non-NULL,
but OOM can cause NULL return which is also unchecked */
hash_step_vformat(&cx,"T%d:",n2);
hash_step(&cx, z2, n2);    /* potential NULL dereference on OOM */
break;
}

/* ext/misc/sha1.c:156-179 — hash_step, the sink function */
static void hash_step(
SHA1Context *p,
const unsigned char *data,    /* may be NULL */
unsigned int len              /* may be 0 */
){
unsigned int i, j;
j = p->count[0];
if( (p->count[0] += len << 3) < j ){
p->count[1] += (len>>29)+1;
}
j = (j >> 3) & 63;
if( (j + len) > 63 ){
(void)memcpy(&p->buffer[j], data, (i = 64-j));  /* reads from NULL if data==NULL and j+len>63 */
SHA1Transform(p->state, p->buffer);
for(; i + 63 < len; i += 64){
SHA1Transform(p->state, &data[i]);
}
j = 0;
}else{
i = 0;
}
(void)memcpy(&p->buffer[j], &data[i], len - i);   /* UB: memcpy(dst, NULL, 0) */
}

/* Compare with the correct NULL check in sha1Func: */
/* ext/misc/sha1.c:266-271 — sha1Func, which DOES check for NULL */
if( eType==SQLITE_BLOB ){
pData = (const unsigned char*)sqlite3_value_blob(argv[0]);
}else{
pData = (const unsigned char*)sqlite3_value_text(argv[0]);
}
if( pData==0 ) return;    /* ← NULL check present in sha1(), but missing in sha1QueryFunc() */
hash_step(&cx, pData, nByte);

PoC-- Trigger NULL pointer dereference in sha1_query via zero-length BLOB
-- On UBSan/hardened builds: runtime error: null pointer passed as argument 2
-- On normal builds: undefined behavior (typically no-op, but could crash)

-- PoC 1: Simple zeroblob trigger
SELECT sha1_query('SELECT zeroblob(0)');

-- PoC 2: Empty BLOB literal
SELECT sha1_query('SELECT X''');

-- PoC 3: Zero-length BLOB from table
CREATE TABLE t(b BLOB);
INSERT INTO t VALUES(zeroblob(0));
SELECT sha1_query('SELECT b FROM t');

-- PoC 4: Multiple zero-length BLOBs in result set
SELECT sha1_query('SELECT zeroblob(0), zeroblob(0), 42');

Fix
Add NULL checks for sqlite3_column_blob() and sqlite3_column_text() return values in sha1QueryFunc(), matching the pattern used in sha1Func():
case SQLITE_BLOB: {
int n2 = sqlite3_column_bytes(pStmt, i);
const unsigned char *z2 = sqlite3_column_blob(pStmt, i);
if( z2==0 && n2==0 ) break;    /* skip zero-length NULL BLOBs */
hash_step_vformat(&cx,"B%d:",n2);
hash_step(&cx, z2, n2);
break;
}
case SQLITE_TEXT: {
int n2 = sqlite3_column_bytes(pStmt, i);
const unsigned char *z2 = sqlite3_column_text(pStmt, i);
if( z2==0 ) break;              /* skip NULL TEXT (OOM) */
hash_step_vformat(&cx,"T%d:",n2);
hash_step(&cx, z2, n2);
break;
}

Summary
SQLite's quote() and unistr_quote() SQL functions (implemented via sqlite3QuoteValue() in src/func.c) use the %Q format specifier in sqlite3_str_appendf(), which reads input strings until a NUL terminator. When a TEXT value contains an embedded NUL byte (\0), the %Q format stops at the first NUL, silently discarding all data after it. The length is available via sqlite3_value_bytes(), but the TEXT branch of sqlite3QuoteValue() discards this information and calls sqlite3_str_appendf(pStr, bEscape ? "%#Q" : "%Q", zArg), relying solely on null-termination.

Consequences:

quote() and unistr_quote() return truncated TEXT values
The .dump command generates INSERT statements that lose data after embedded NULs
Database backup/restore cycles silently corrupt TEXT data containing NUL bytes
substr() with negative offset returns incorrect results for TEXT with embedded NULs
length() for TEXT returns incorrect character counts (stops at NUL)

Vulnerable Code
Primary: sqlite3QuoteValue() TEXT branch — src/func.c:1158-1161case SQLITE_TEXT: {
const unsigned char *zArg = sqlite3_value_text(pValue);
sqlite3_str_appendf(pStr, bEscape ? "%#Q" : "%Q", zArg);
break;
}

The length sqlite3_value_bytes(pValue) IS available (as demonstrated by the BLOB branch on lines 1138-1156), but the TEXT branch uses %Q which relies on null-termination. Contrast with the correct BLOB branch:
case SQLITE_BLOB: {
char const *zBlob = sqlite3_value_blob(pValue);
i64 nBlob = sqlite3_value_bytes(pValue);  // <-- length used correctly
assert( zBlob==sqlite3_value_blob(pValue) );
sqlite3StrAccumEnlarge(pStr, nBlob*2 + 4);
if( pStr->accError==0 ){
char *zText = pStr->zText;
int i;
for(i=0; i<nBlob; i++){             // <-- iterates by byte count, not NUL
zText[(i*2)+2] = hexdigits[(zBlob[i]>>4)&0x0F];
zText[(i*2)+3] = hexdigits[(zBlob[i])&0x0F];
}
// ...
}
break;
}

Root cause: %Q format in src/printf.c:982-988k = precision;
for(i=n=0; k!=0 && (ch=escarg[i])!=0; i++, k--){
if( ch==q )  n++;
if( flag_altform2 && (ch&0xc0)==0xc0 ){
while( (escarg[i+1]&0xc0)==0x80 ){ i++; }
}
}

The loop condition (ch=escarg[i])!=0 stops at the first NUL byte. When called without explicit precision (as in %Q), k is set to -1 (never reaches 0), so the loop terminates solely on the NUL byte.

Secondary: substrFunc() negative offset — src/func.c:382-387z = sqlite3_value_text(argv[0]);
if( z==0 ) return;
len = 0;
if( p1<0 ){
for(z2=z; *z2; len++){
SQLITE_SKIP_UTF8(z2);
}
}

When computing the length for negative offset calculation, the function uses *z2 as the termination condition instead of sqlite3_value_bytes(argv[0]), which is available and used correctly for the BLOB case on line 375.

Secondary: lengthFunc() for TEXT — src/func.c:130-147case SQLITE_TEXT: {
const unsigned char *z = sqlite3_value_text(argv[0]);
const unsigned char *z0;
if( z==0 ) return;
z0 = z;
while( 1 /*exit-by-break*/ ){
if( (u8)(z[0]-1)<(0x80-1) ){
z++;
}else if( z[0]==0 ){
break;          // <-- stops at embedded NUL
}else{
z++;
while( (z[0]&0xc0)==0x80 ){ z++; z0++; }
}
}
sqlite3_result_int(context, (int)(z-z0));
break;
}

Uses NUL-terminated iteration instead of sqlite3_value_bytes(). The BLOB case on line 124 correctly uses sqlite3_value_bytes(argv[0]).

PoC-- Create table with embedded NUL in TEXT column
CREATE TABLE t(id INTEGER PRIMARY KEY, data TEXT);
INSERT INTO t VALUES(1, 'role=user' || X'00' || 'escalate=true');

-- Verify full data is stored (23 bytes, hex includes data after NUL)
SELECT hex(data), octet_length(data) FROM t WHERE id=1;
-- Expected: 726F6C653D7573657200657363616C6174653D74727565|23

-- quote() truncates at embedded NUL (only 9 bytes output, loses 14 bytes)
SELECT quote(data), length(quote(data)) FROM t WHERE id=1;
-- Got: 'role=user'|9     (14 bytes lost!)

-- unistr_quote() also truncates
SELECT unistr_quote(data) FROM t WHERE id=1;
-- Got: 'role=user'      (14 bytes lost!)

-- BLOB version works correctly (uses sqlite3_value_bytes)
SELECT quote(CAST(data AS BLOB)) FROM t WHERE id=1;
-- Got: X'726F6C653D7573657200657363616C6174653D74727565' (correct!)

-- .dump generates incorrect INSERT (data loss!)
.dump
-- Got: INSERT INTO t VALUES(1,'role=user');
-- Expected: INSERT INTO t VALUES(1,X'726F6C653D7573657200657363616C6174653D74727565');

-- substr() with negative offset gives wrong result
SELECT substr('abcdef' || X'00' || 'ghij', -2);
-- Got: 'ef'  (wrong: should be 'ij')

-- length() stops at NUL, octet_length() is correct
SELECT length('hello' || X'00' || 'world'), octet_length('hello' || X'00' || 'world');
-- Got: 5|11  (length=5 stops at NUL, octet_length=11 is correct)

