--                                ^^^^^^^^^^ truncated at NUL, 'escalate=true' lost

-- After restore, the metadata column has only 9 bytes instead of 23
-- "escalate=true" (14 bytes) is permanently lost

Fix Suggestion
For sqlite3QuoteValue() TEXT branch (src/func.c:1158-1161), detect embedded NULs and fall back to BLOB-style hex encoding:
case SQLITE_TEXT: {
const unsigned char *zArg = sqlite3_value_text(pValue);
int nArg = sqlite3_value_bytes(pValue);
if( nArg>0 && (int)strlen((const char*)zArg)!=nArg ){
/* Text contains embedded NUL bytes - use hex encoding to preserve data */
int i;
sqlite3StrAccumEnlarge(pStr, nArg*2 + 4);
if( pStr->accError==0 ){
char *zText = pStr->zText;
zText[0] = 'X';
zText[1] = '\'';
for(i=0; i<nArg; i++){
zText[(i*2)+2] = hexdigits[(zArg[i]>>4)&0x0F];
zText[(i*2)+3] = hexdigits[(zArg[i])&0x0F];
}
zText[(nArg*2)+2] = '\'';
zText[(nArg*2)+3] = '\0';
pStr->nChar = nArg*2 + 3;
}
}else{
sqlite3_str_appendf(pStr, bEscape ? "%#Q" : "%Q", zArg);
}
break;
}

For substrFunc() negative offset (src/func.c:382-387), use sqlite3_value_bytes() for TEXT as the BLOB case does:
if( p0type==SQLITE_BLOB ){
len = sqlite3_value_bytes(argv[0]);
z = sqlite3_value_blob(argv[0]);
// ...
}else{
z = sqlite3_value_text(argv[0]);
if( z==0 ) return;
len = 0;
if( p1<0 ){
/* Use byte count + UTF-8 character counting instead of NUL termination */
int nBytes = sqlite3_value_bytes(argv[0]);
const unsigned char *z2b = z;
while( nBytes>0 ){
SQLITE_SKIP_UTF8(z2b);
nBytes -= (int)(z2b - z) - (len>0 ? SQLITE_UTF8_LEN(z, len) : 0);
len++;
}
}
}

Or more simply, for the negative offset case, count characters using the known byte length:
if( p1<0 ){
int nBytes = sqlite3_value_bytes(argv[0]);
for(z2=z; nBytes>0; len++){
SQLITE_SKIP_UTF8(z2);
nBytes -= (int)(z2 - z - (len>0 ? 0 : 0));
}
}

Summary
sqlite3ExprAffinity() in src/expr.c:45 does not traverse through TK_UPLUS (unary plus +) expressions, incorrectly returning SQLITE_AFF_BLOB (0) instead of the child expression's actual affinity. This violates the documented behavior that unary plus is a "no-op" that preserves the operand's value and type. The wrong affinity causes comparison operators (>, <, =, BETWEEN, IN, CASE WHEN) to use incorrect type coercion semantics, producing wrong query results for +text_column compared with numeric values. It also causes CREATE TABLE AS SELECT +column to create columns with BLOB affinity instead of the source column's affinity.

This is structurally identical to the recently fixed sqlite3ExprCanReturnSubtype() bug (commit 1e4ec59e3f), which also failed to traverse through TK_UPLUS. The same class of bug exists in sqlite3ExprAffinity(), but with more severe impact: wrong comparison results instead of just lost subtypes.

Vulnerable Code
File: src/expr.c, lines 45-94
char sqlite3ExprAffinity(const Expr *pExpr){
int op;
op = pExpr->op;
while( 1 ){
if( op==TK_COLUMN || (op==TK_AGG_COLUMN && pExpr->y.pTab!=0) ){
// ... handles TK_COLUMN ...
}
if( op==TK_SELECT ){ /* ... */ }
if( op==TK_CAST ){ /* ... */ }
if( op==TK_SELECT_COLUMN ){ /* ... */ }
if( op==TK_VECTOR || (op==TK_FUNCTION && pExpr->affExpr==SQLITE_AFF_DEFER) ){ /* ... */ }
if( ExprHasProperty(pExpr, EP_Skip|EP_IfNullRow) ){
// handles TK_COLLATE and TK_IF_NULL_ROW
pExpr = pExpr->pLeft;
op = pExpr->op;
continue;
}
if( op!=TK_REGISTER ) break;   // <-- TK_UPLUS breaks here!
op = pExpr->op2;
}
return pExpr->affExpr;  // Returns 0 (SQLITE_AFF_BLOB) for TK_UPLUS
}

Missing: There is no if( op==TK_UPLUS ) case to traverse through to the child expression. The function falls through to return pExpr->affExpr which returns 0 (SQLITE_AFF_BLOB) for UPLUS nodes created by sqlite3PExpr().

Contrast with correct implementations:

