Summary
sqlite3_drop_modules() walks db->aModule without first holding the
connection mutex, while sqlite3_create_module() and
sqlite3_create_module_v2() mutate the same hash under that mutex. Concurrent
documented API use on a serialized connection can free hash elements while the
drop loop still dereferences them.

Affected Area

SQLite version or Fossil check-in: 3.54.0 / dc4763b14c421710f2a19c19c1cac455c1d0
Build options or relevant feature flags: Default threadsafe amalgamation
build; shared connection opened with SQLITE_OPEN_FULLMUTEX.
Component or source path: src/vtab.c, sqlite3_drop_modules(), and the
sqlite3_create_module() / sqlite3_create_module_v2() path.

Steps to Reproduce
The main thread loops on sqlite3_drop_modules() while one worker removes and
re-adds the same module with sqlite3_create_module() on the same FULLMUTEX
connection. The keep list only lengthens the unlocked name scan.

PoC Source
poc.c:
#include "sqlite3.h"

#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>

#define KEEP_SCAN_COUNT 10000
#define DROP_ROUNDS 1000
#define MODULE_NAME "target"

static sqlite3 *g_db;
static const sqlite3_module g_module = {
.iVersion = 3,
};
static atomic_int g_stop;

static void die_sqlite(const char *op, int rc) {
fprintf(stderr, "%s failed: rc=%d msg=%s\n", op, rc, sqlite3_errmsg(g_db));
exit(1);
}

static void *mutate_module(void *unused) {
(void)unused;
while (atomic_load_explicit(&g_stop, memory_order_relaxed) == 0) {
int rc = sqlite3_create_module(g_db, MODULE_NAME, NULL, NULL);
if (rc != SQLITE_OK) {
die_sqlite("remove module", rc);
}
rc = sqlite3_create_module(g_db, MODULE_NAME, &g_module, NULL);
if (rc != SQLITE_OK) {
die_sqlite("add module", rc);
}
}
return NULL;
}

int main(void) {
const char *keep[KEEP_SCAN_COUNT + 2];
pthread_t thread;
int rc;

/* Keep sqlite3_drop_modules() in its unlocked name scan long enough to race. */
for (int i = 0; i < KEEP_SCAN_COUNT; i++) {
keep[i] = "not-target";
}
keep[KEEP_SCAN_COUNT] = MODULE_NAME;
keep[KEEP_SCAN_COUNT + 1] = NULL;

rc = sqlite3_open_v2(
":memory:",
&g_db,
SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX,
NULL);
if (rc != SQLITE_OK) {
die_sqlite("sqlite3_open_v2", rc);
}
rc = sqlite3_create_module(g_db, MODULE_NAME, &g_module, NULL);
if (rc != SQLITE_OK) {
die_sqlite("initial sqlite3_create_module", rc);
}
if (pthread_create(&thread, NULL, mutate_module, NULL) != 0) {
perror("pthread_create");
return 1;
}

for (int i = 0; i < DROP_ROUNDS; i++) {
rc = sqlite3_drop_modules(g_db, keep);
if (rc != SQLITE_OK) {
die_sqlite("sqlite3_drop_modules", rc);
}
}

atomic_store_explicit(&g_stop, 1, memory_order_relaxed);
pthread_join(thread, NULL);
fprintf(stderr, "no sanitizer finding\n");
sqlite3_close(g_db);
return 2;
}

Expected Behavior
Public module-management calls on a serialized connection should be internally
serialized, with no hash iteration over freed elements.

Actual Behavior
ASan reports heap-use-after-free in sqlite3_drop_modules() while iterating
module hash elements.

Impact
Memory safety violation: documented cross-thread API use can cause
use-after-free and process memory corruption.

Evidence
In src/vtab.c, sqlite3_drop_modules() calls
sqliteHashFirst(), sqliteHashData(), and sqliteHashNext() before taking
db->mutex. The createModule() path used by both module registration APIs
takes the mutex and can unlink and free those same HashElem nodes
concurrently.

