Fix/* ext/misc/closure.c closureDequote(): always terminate the dequoted output. */
if( q=='[' ) q = ']';
for(iIn=1; iIn<nIn; iIn++){
if( zIn[iIn]==q ) iIn++;
zOut[iOut++] = zIn[iIn];
