Summary
Shadow-table status is cached when schema objects are loaded, but registering a
virtual table module later does not rescan already loaded schemas. A table that
should gain TF_Shadow can remain an ordinary table and stay writable under
SQLITE_DBCONFIG_DEFENSIVE.

Affected Area

SQLite version or Fossil check-in: 3.54.0 / dc4763b14c421710f2a19c19c1cac455c1d0
Build options or relevant feature flags: Default amalgamation build; virtual
table module with xShadowName registered after schema load.
Component or source path: src/build.c, sqlite3MarkAllShadowTablesOf(),
and sqlite3_create_module_v2() in src/vtab.c.

Steps to Reproduce
The PoC compares early and late registration of a module whose xShadowName
recognizes ft_data:

Create a database with virtual table ft and backing table ft_data.
Reopen it with the module registered before schema load; defensive mode
blocks UPDATE ft_data ....
Reopen it again, load the schema before registering the same module, and
show that defensive mode now allows the same UPDATE ft_data ....

PoC Source
poc.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "sqlite3.h"

#ifndef POC_DIR
#define POC_DIR "."
#endif

#define DB_PATH POC_DIR "/late-vtab.db"

static void die(sqlite3 *db, const char *op, int rc) {
fprintf(stderr, "%s failed: rc=%d err=%s\n", op, rc, sqlite3_errmsg(db));
exit(1);
}

static void exec_sql(sqlite3 *db, const char *sql) {
char *err = NULL;
int rc = sqlite3_exec(db, sql, NULL, NULL, &err);

if (rc != SQLITE_OK) {
fprintf(stderr, "%s\n  rc=%d err=%s\n", sql, rc, err ? err : "<none>");
sqlite3_free(err);
exit(1);
}
}

static int connect_vtab(
sqlite3 *db,
void *unused,
int argc,
const char *const *argv,
sqlite3_vtab **out,
char **err) {
sqlite3_vtab *vtab = sqlite3_malloc(sizeof(*vtab));
int rc;

(void)unused;
(void)argc;
(void)argv;
(void)err;

if (vtab == NULL) {
return SQLITE_NOMEM;
}
memset(vtab, 0, sizeof(*vtab));

rc = sqlite3_declare_vtab(db, "CREATE TABLE x(value)");
if (rc != SQLITE_OK) {
sqlite3_free(vtab);
return rc;
}

*out = vtab;
return SQLITE_OK;
}

static int disconnect_vtab(sqlite3_vtab *vtab) {
sqlite3_free(vtab);
return SQLITE_OK;
}

static int is_shadow_name(const char *suffix) {
return sqlite3_stricmp(suffix, "data") == 0;
}

static const sqlite3_module demo_module = {
.iVersion = 3,
.xCreate = connect_vtab,
.xConnect = connect_vtab,
.xDisconnect = disconnect_vtab,
.xDestroy = disconnect_vtab,
.xShadowName = is_shadow_name,
};

static void register_module(sqlite3 *db) {
int rc = sqlite3_create_module_v2(db, "shadowmod", &demo_module, NULL, NULL);
if (rc != SQLITE_OK) {
die(db, "sqlite3_create_module_v2", rc);
}
}

static int update_shadow(sqlite3 *db) {
char *err = NULL;
int rc = sqlite3_exec(
db,
"UPDATE ft_data SET block=X'3344' WHERE id=1",
NULL,
NULL,
&err);

printf("  update rc=%d err=%s\n", rc, err ? err : "<none>");
sqlite3_free(err);
return rc;
}

static void create_database(void) {
sqlite3 *db = NULL;
int rc;

remove(DB_PATH);
rc = sqlite3_open(DB_PATH, &db);
if (rc != SQLITE_OK) {
die(db, "sqlite3_open create", rc);
}

register_module(db);
exec_sql(
db,
"CREATE VIRTUAL TABLE ft USING shadowmod;"
"CREATE TABLE ft_data(id INTEGER PRIMARY KEY, block BLOB);"
"INSERT INTO ft_data VALUES(1, X'1122');");
sqlite3_close(db);
}

static void run_case(const char *label, int register_before_schema_load) {
sqlite3 *db = NULL;
int old_value = 0;
int update_rc;
int rc;

rc = sqlite3_open(DB_PATH, &db);
if (rc != SQLITE_OK) {
die(db, "sqlite3_open", rc);
}

if (register_before_schema_load) {
register_module(db);
} else {
exec_sql(db, "SELECT name FROM sqlite_schema");
register_module(db);
}

rc = sqlite3_db_config(db, SQLITE_DBCONFIG_DEFENSIVE, 1, &old_value);
if (rc != SQLITE_OK) {
die(db, "sqlite3_db_config", rc);
}

update_rc = update_shadow(db);
printf("%s: update %s\n", label, update_rc == SQLITE_OK ? "allowed" : "blocked");

if (register_before_schema_load) {
if (update_rc == SQLITE_OK) {
fputs("FAIL: early registration should protect ft_data\n", stderr);
exit(1);
}
} else if (update_rc != SQLITE_OK) {
fputs("FAIL: late registration should leave ft_data writable\n", stderr);
exit(1);
}

sqlite3_close(db);
}

int main(void) {
create_database();

puts("1. Register module before schema load:");
run_case("early", 1);

puts("2. Load schema before registering module:");
run_case("late", 0);

return 0;
}

Expected Behavior
Registering a module with xShadowName should mark matching existing tables as
shadow tables before defensive-mode write checks can observe them.

Actual Behavior
Early registration blocks the direct UPDATE ft_data ... statement. Loading
the schema first and registering the same module afterward allows the same
update under defensive mode.

Impact
Integrity loss and durable denial of service: direct writes to virtual-table
backing storage can corrupt indexes or internal state despite defensive mode.

Evidence
In src/build.c, sqlite3MarkAllShadowTablesOf() returns when the
module is not yet present during schema load. sqlite3_create_module_v2() in
src/vtab.c adds the module later but does not rescan loaded schemas to set
TF_Shadow.

Suggested Fix
Rescan loaded schemas for matching shadow tables when a module with
xShadowName is registered after schema load. Add virtual-table tests in
test/vtab*.test that load schema before module registration, enable defensive
mode, and require shadow-table writes to fail.

