#include <stdio.h>
#include "sqlite3.h"

static int nHit = 0;

static int auth(void *p,int op,const char *a0,const char *a1,
const char *a2,const char *a3){
(void)p;(void)a2;(void)a3;
if( op==SQLITE_READ ) printf("    READ %s.%s\n", a0, a1);
if( op==SQLITE_READ && !sqlite3_stricmp(a0,"b") && !sqlite3_stricmp(a1,"x") ){
nHit++;
return SQLITE_DENY;                 /* b.x is protected */
}
return SQLITE_OK;
}

static void tryq(sqlite3 *db, const char *zSql){
sqlite3_stmt *pStmt = 0;
nHit = 0;
printf("%s\n", zSql);
if( sqlite3_prepare_v2(db, zSql, -1, &pStmt, 0)!=SQLITE_OK ){
printf("    => BLOCKED: %s\n\n", sqlite3_errmsg(db));
return;
}
while( sqlite3_step(pStmt)==SQLITE_ROW ){
printf("    => ROW: x = %s\n", sqlite3_column_text(pStmt,0));
}
printf("    (b.x authorizer callbacks: %d)\n\n", nHit);
sqlite3_finalize(pStmt);
}

int main(void){
sqlite3 *db;
sqlite3_open(":memory:", &db);
sqlite3_exec(db, "CREATE TABLE b(x TEXT); INSERT INTO b VALUES('b-only');", 0,0,0);
sqlite3_set_authorizer(db, auth, 0);
printf("%s\n\n", sqlite3_libversion());
tryq(db, "SELECT x FROM b");
tryq(db, "SELECT coalesce(NULL, b.x) AS x FROM b");
tryq(db, "WITH q(x) AS (SELECT NULL WHERE 0)"
" SELECT coalesce(q.x, b.x) AS x FROM q FULL JOIN b ON q.x IS b.x");
tryq(db, "WITH q(x) AS (SELECT NULL WHERE 0)"
" SELECT x FROM q FULL JOIN b USING(x)");
sqlite3_close(db);
return 0;
}

Build with cc -O0 -o minrepro minrepro.c sqlite3.c -lpthread -ldl -lm.

Output at trunk 7bc7e25c:

3.54.0

SELECT x FROM b
READ b.x
=> BLOCKED: access to b.x is prohibited

SELECT coalesce(NULL, b.x) AS x FROM b
READ b.x
=> BLOCKED: access to b.x is prohibited

WITH q(x) AS (SELECT NULL WHERE 0) SELECT coalesce(q.x, b.x) AS x FROM q FULL JOIN b ON q.x IS b.x
READ b.x
=> BLOCKED: access to b.x is prohibited

WITH q(x) AS (SELECT NULL WHERE 0) SELECT x FROM q FULL JOIN b USING(x)
READ q.x
READ q.x
=> ROW: x = b-only
(b.x authorizer callbacks: 0)

The last case returns the protected value, prepare succeeds, and no diagnostic is produced. The third case is the same query written with an explicit coalesce() and is correctly denied, which is the cleanest sign this is the rewrite path rather than intended join semantics. The doubled READ q.x is the duplicated element 0.

With the a[ii] change the last case becomes:

READ q.x
READ b.x
=> BLOCKED: access to b.x is prohibited

An N-way chain leaves N-1 columns unauthorized. With a FULL JOIN b USING(x) FULL JOIN c USING(x), denying b.x or c.x has no effect at all.

4. Released versions
Neither ddea119f8 (2026-06-01, for Bug 2026-05-31T02:00:37Z) nor bbd69ce274 (2026-07-05) is present in any 3.53.x release. In the official 3.53.3 amalgamation from sqlite.org, sqlite3.c line 111319:

lookupname_end:
if( cnt==1 ){
assert( pNC!=0 );
#ifndef SQLITE_OMIT_AUTHORIZATION
if( pParse->db->xAuth
&& (pExpr->op==TK_COLUMN || pExpr->op==TK_TRIGGER)
){
sqlite3AuthRead(pParse, pExpr, pSchema, pNC->pSrcList);
}

After the rewrite pExpr->op is TK_FUNCTION, so the guard is false and no callback is issued for any term, including the first. Running the reproducer above against the official 3.39.0, 3.53.1, and 3.53.3 amalgamations gives zero SQLITE_READ callbacks for the shared column and returns the protected value in every case.

I mention it only because both tracker entries read Resolved, which could suggest to someone checking their version that a shipped release carries the fix.

One question, so that downstream users have something to check against: will the next release note that 3.39.0 through 3.53.3 are affected, or is the intent to fix trunk only?

5. Minor: reachable assert on SQLITE_IGNORE
sqlite3AuthRead() implements SQLITE_IGNORE by setting pExpr->op = TK_NULL in place. Because the loop re-submits element 0, an authorizer returning SQLITE_IGNORE for the first column nulls it on iteration 0 and then fails assert( pFJMatch->a[0].pExpr->op==TK_COLUMN ) on iteration 1. In a -DSQLITE_DEBUG build:

lookupName: Assertion `pFJMatch->a[0].pExpr->op==TK_COLUMN' failed.  Aborted

Trigger: SELECT x FROM a FULL JOIN b USING(x) with SQLITE_IGNORE on READ a.x. The a[ii] change resolves this as well, since each element is then visited once.

