Reproduction:/*
** Standalone reproducer for an MVCC corruption bug in hctree's
** sqlite3_hct_journal_setmode(SQLITE_HCT_LEADER).
**
** Root cause: pagemap slot 16 is HCT_PAGEMAP_TRANSID_EOF (the global
** transaction-id counter), but pagemap slots also carry per-page flag
** bits in their top byte, and the HCT_PMF_PHYSICAL_IN_USE flag for
** physical page 16 lands in that same slot. sqlite3HctFilePeekTransid()
** returns the slot without masking the flag byte, so whenever physical
** page 16 is in use it reports the current TID with bit 58 set (~2^58).
** setmode(LEADER) uses that value to rebuild the transaction map, which
** ends up covering TIDs near 2^58. Every real TID then sits below the
** map's floor, which hctree treats as "committed long ago, visible to
** every snapshot" - disabling snapshot isolation and write-write
** conflict detection for all subsequent transactions.
**
** This program provokes it with one connection: create a table, insert
** enough rows that physical page 16 is in use, then init the journal
** and enter LEADER mode. A reader opened after the transition pins a
** snapshot, and still observes a row committed afterwards by
** sqlite3_hct_journal_leader_commit() on another connection.
**
** Exit status: 0 = isolation held, 1 = bug reproduced, 2 = error.
*/
#include "sqlite3.h"
#include "sqlite3hct.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void fail_db(sqlite3 *db, const char *what, int rc){
fprintf(stderr, "%s: rc=%d extended=%d: %s\n", what, rc,
db ? sqlite3_extended_errcode(db) : rc,
db ? sqlite3_errmsg(db) : sqlite3_errstr(rc));
exit(2);
}

static void check_rc(sqlite3 *db, const char *what, int rc){
if( rc!=SQLITE_OK ) fail_db(db, what, rc);
}

static void exec_sql(sqlite3 *db, const char *what, const char *sql){
char *zErr = 0;
int rc = sqlite3_exec(db, sql, 0, 0, &zErr);
if( rc!=SQLITE_OK ){
fprintf(stderr, "%s: rc=%d extended=%d: %s\n", what, rc,
sqlite3_extended_errcode(db), zErr ? zErr : sqlite3_errmsg(db));
sqlite3_free(zErr);
exit(2);
}
}

static sqlite3_int64 scalar_int(sqlite3 *db, const char *what, const char *sql){
sqlite3_stmt *pStmt = 0;
sqlite3_int64 value;
int rc = sqlite3_prepare_v2(db, sql, -1, &pStmt, 0);
if( rc!=SQLITE_OK ) fail_db(db, what, rc);
rc = sqlite3_step(pStmt);
if( rc!=SQLITE_ROW ) fail_db(db, what, rc);
value = sqlite3_column_int64(pStmt, 0);
rc = sqlite3_finalize(pStmt);
if( rc!=SQLITE_OK ) fail_db(db, what, rc);
return value;
}

static sqlite3 *open_db(const char *zUri, const char *what){
sqlite3 *db = 0;
int flags = SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_URI;
int rc = sqlite3_open_v2(zUri, &db, flags, 0);
if( rc!=SQLITE_OK ) fail_db(db, what, rc);
check_rc(db, "enable extended result codes",
sqlite3_extended_result_codes(db, 1));
return db;
}

int main(int argc, char **argv){
const char *zPath = argc>1 ? argv[1] : "repro.db";
char *zUri = sqlite3_mprintf("file:%s?hctree=1", zPath);
sqlite3 *writer;
sqlite3 *reader;
sqlite3_int64 cid = 0;
sqlite3_int64 snapshot = 0;
sqlite3_int64 inUse;
sqlite3_int64 before;
sqlite3_int64 afterPoint;
sqlite3_int64 afterScan;
const unsigned char payload[] = {'p'};
int rc;
int bug;

if( zUri==0 ){
fprintf(stderr, "out of memory\n");
return 2;
}
if( remove(zPath)!=0 && errno!=ENOENT ){
fprintf(stderr, "cannot remove existing database: %s: %s\n",
zPath, strerror(errno));
sqlite3_free(zUri);
return 2;
}

printf("SQLite %s\nsource-id %s\n", sqlite3_libversion(), sqlite3_sourceid());

writer = open_db(zUri, "open writer");

/* Grow the database so that physical page 16 is in use. Any workload
** that leaves page 16 allocated works; a table plus a few thousand rows
** is deterministic. */
exec_sql(writer, "create user table",
"CREATE TABLE t(id INTEGER PRIMARY KEY, v TEXT)");
exec_sql(writer, "insert filler rows",
"WITH RECURSIVE c(x) AS (SELECT 2 UNION ALL SELECT x+1 FROM c WHERE x<2000)"
" INSERT INTO t SELECT x, 'filler-row-payload' FROM c");

/* Predictor: the bug fires iff the TRANSID_EOF pagemap slot carries the
** HCT_PMF_PHYSICAL_IN_USE flag when setmode(LEADER) runs. */
inUse = scalar_int(writer, "read pagemap slot 16",
"SELECT physical_in_use FROM hctpgmap WHERE slot=16");
printf("pagemap slot 16 (TRANSID_EOF): physical_in_use=%lld\n",
(long long)inUse);
if( inUse==0 ){
fprintf(stderr, "note: physical page 16 not in use; the transition "
"below will not be poisoned on this run\n");
}

check_rc(writer, "sqlite3_hct_journal_init",
sqlite3_hct_journal_init(writer));
check_rc(writer, "sqlite3_hct_journal_setmode(LEADER)",
sqlite3_hct_journal_setmode(writer, SQLITE_HCT_LEADER));
if( sqlite3_hct_journal_mode(writer)!=SQLITE_HCT_LEADER ){
fprintf(stderr, "database did not enter LEADER mode\n");
return 2;
}

/* The reader does not exist until after the mode transition. */
reader = open_db(zUri, "open reader");

exec_sql(writer, "begin writer", "BEGIN CONCURRENT");
exec_sql(writer, "insert user row", "INSERT INTO t VALUES(1, 'x')");

exec_sql(reader, "begin reader", "BEGIN CONCURRENT");
(void)scalar_int(reader, "pin reader snapshot",
"SELECT count(*) FROM sqlite_schema");
before = scalar_int(reader, "read before commit",
"SELECT count(*) FROM t WHERE id=1");

rc = sqlite3_hct_journal_leader_commit(
writer, payload, (int)sizeof(payload), &cid, &snapshot
);
check_rc(writer, "sqlite3_hct_journal_leader_commit", rc);

afterPoint = scalar_int(reader, "point read after commit",
"SELECT EXISTS(SELECT 1 FROM t WHERE id=1)");
afterScan = scalar_int(reader, "scan after commit",
"SELECT count(*) FROM t WHERE id=1");

printf("reader in one open transaction: before=%lld, "
"after-point=%lld, after-scan=%lld\n",
(long long)before, (long long)afterPoint, (long long)afterScan);
/* snapshot==0 here is a fingerprint of the poisoned transition: every
** TID the writer observed mapped to CID 0. A healthy run reports 1. */
printf("leader commit: cid=%lld snapshot=%lld\n",
(long long)cid, (long long)snapshot);

bug = before==0 && (afterPoint!=0 || afterScan!=0);
fflush(stdout);
if( bug ){
fprintf(stderr,
"BUG: the pinned reader observed a concurrent leader_commit\n");
}else if( before!=0 ){
fprintf(stderr, "unexpected pre-commit result: expected 0\n");
}else{
printf("OK: the pinned reader remained on its original snapshot\n");
}

exec_sql(reader, "rollback reader", "ROLLBACK");
check_rc(reader, "close reader", sqlite3_close(reader));
check_rc(writer, "close writer", sqlite3_close(writer));
sqlite3_free(zUri);
return bug ? 1 : (before==0 ? 0 : 2);
}

With the help of Claude, I hunted down the issue. I asked it to summarize:

Bug: SEGV in readline after Ctrl-C during incremental search (Ctrl-R)
Summary
Interrupting an active incremental search (Ctrl-R) with SIGINT (Ctrl-C), then pressing Enter, causes a segmentation fault inside readline's isearch cleanup path.

Steps to reproduce

Start the CLI (readline built-in line editing enabled)
Press Ctrl-R to begin reverse history search
Press Ctrl-C
Press Enter
Program crashes with SIGSEGV

Environment

Readline version: 8.3.2
Signal handling: program installs its SIGINT handler via signal(), not sigaction()

Crash location#0  update_line (...) at ../display.c:2205
#1  rl_redisplay () at ../display.c:1366
#2  rl_clear_message () at ../display.c:3192
#3  _rl_isearch_fini (cxt=0x5eca40) at ../isearch.c:311
#4  _rl_isearch_cleanup (cxt=0x5eca40, r=0) at ../isearch.c:893
#5  _rl_dispatch_subseq (...) at ../readline.c:944
#6  _rl_dispatch (...) at ../readline.c:879
#7  readline_internal_char () at ../readline.c:693

old/new line-state buffers passed to update_line contain garbage/freed memory, indicating use of a stale isearch context.

Root cause
Because the signal was delivered while execution was inside readline's isearch dispatch code (_rl_dispatch_subseq → _rl_isearch_cleanup), returning from the handler resumed execution inside those same interrupted C frames, which then continued operating on state the handler had just freed/reset. The subsequent Enter keypress drove execution into _rl_isearch_fini/rl_redisplay using a dangling isearch context pointer, causing the SEGV.

The problem is that a handler which mutates readline's state and returns normally resumes mid-way through now-invalid readline internals rather than unwinding safely.

Fix

Use sigsetjmp/siglongjmp to unwind out of the interrupted readline() call entirely instead of returning from the handler into corrupted state. Cleanup (rl_free_line_state(), rl_cleanup_after_signal(), RL_UNSETSTATE(...), rl_reset_after_signal()) runs after the siglongjmp lands in the main input loop. Set rl_catch_signals = 0  before calling readline() to disable its signal handler.
On the second Ctrl-C (the handler's existing "exit on second interrupt" behavior), restore terminal state (rl_free_line_state() + rl_cleanup_after_signal()) before calling cli_exit(). Previously the process exited without restoring the terminal, leaving it in raw mode for the next program run in that shell (visible as Enter echoing as ^M).
Recommend switching handler installation from signal() to sigaction() for portable, well-defined re-registration semantics, though this was not the root cause of the crash.

