#2 oF                 oom_mock_static.c:26
#3 sqlite3_free       sqlite3.c:32093
#4 editDist3Install   ext/misc/spellfix.c:1236   <- sqlite3_free(pConfig) in the else branch
#5 spellfix1Register  ext/misc/spellfix.c:3055
