The nArg=2 registration (line 1215) succeeded, nArg=3 (line 1219) failed under the injected OOM, pConfig was freed in the else branch (line 1228, reported here as line 1236 in the exact trunk build's line numbering), and the still-live editdist3/2 function's pApp was left pointing at the freed 24-byte region. SELECT editdist3('kitten','sitting') then dereferenced it via sqlite3_user_data().

Fix
Free pConfig only when nothing has been registered with it yet, and explicitly tear down any partial registrations otherwise, so no live function is left pointing at freed memory:
static int editDist3Install(sqlite3 *db){
int rc;
EditDist3Config *pConfig = sqlite3_malloc64( sizeof(*pConfig) );
if( pConfig==0 ) return SQLITE_NOMEM;
memset(pConfig, 0, sizeof(*pConfig));
rc = sqlite3_create_function_v2(db, "editdist3",
2, SQLITE_UTF8|SQLITE_DETERMINISTIC, pConfig,
editDist3SqlFunc, 0, 0, 0);
if( rc==SQLITE_OK ){
rc = sqlite3_create_function_v2(db, "editdist3",
3, SQLITE_UTF8|SQLITE_DETERMINISTIC, pConfig,
editDist3SqlFunc, 0, 0, 0);
}
if( rc==SQLITE_OK ){
rc = sqlite3_create_function_v2(db, "editdist3",
1, SQLITE_UTF8|SQLITE_DETERMINISTIC, pConfig,
editDist3SqlFunc, 0, 0, editDist3ConfigDelete);
}else{
/* Undo whichever of the earlier registrations already succeeded, so no
** live "editdist3" entry is left pointing pApp at pConfig, then free it
** exactly once. */
sqlite3_create_function_v2(db, "editdist3", 2, SQLITE_UTF8, 0, 0,0,0,0);
sqlite3_create_function_v2(db, "editdist3", 3, SQLITE_UTF8, 0, 0,0,0,0);
sqlite3_free(pConfig);
}
return rc;
}

