Compiles under GCC and Clang with the runtime byte-order fallback, the
forced big-endian path, and SQLITE_OMIT_FLOATING_POINT; a
SQLITE_BYTEORDER=0 build runs fp with the expected hash. Not executed
on real big-endian hardware.

Costs and caveats

Code size: .text +472 bytes on Linux GCC/x86-64 (comparator 391
bytes), __text +616 bytes on macOS Clang/ARM64.
Only sorts/index builds with an eligible numeric leading key benefit.
The insert-path classification is nearly free for everything else: an
intentionally all-NULL microbenchmark showed the largest effect at
+0.065% instructions (~0.7% slower); INTEGER/BLOB/TEXT were neutral
(table above).
NaN handling mirrors serialGet() (IsNaN tested after
swapMixedEndianFloat()), so fast-path and generic results agree on
all byte orders, including SQLITE_MIXED_ENDIAN_64BIT_FLOAT.

Patch--- src/vdbesort.c
+++ src/vdbesort.c
@@ -341,6 +341,7 @@

#define SORTER_TYPE_INTEGER 0x01
#define SORTER_TYPE_TEXT    0x02
+#define SORTER_TYPE_REAL    0x04

/*
** An instance of the following object is used to read records out of a
@@ -915,6 +916,101 @@
}

/*
+** Read an 8-byte big-endian IEEE-754 value without assuming alignment.
+*/
+static u64 vdbeSorterGetRealBits(const u8 *p){
+#if SQLITE_BYTEORDER==1234 && GCC_VERSION>=4003000
+  u64 x;
+  memcpy(&x, p, sizeof(x));
+  return __builtin_bswap64(x);
+#elif SQLITE_BYTEORDER==1234 && MSVC_VERSION>=1300
+  u64 x;
+  memcpy(&x, p, sizeof(x));
+  return _byteswap_uint64(x);
+#elif SQLITE_BYTEORDER==4321
+  u64 x;
+  memcpy(&x, p, sizeof(x));
+  return x;
+#else
+  return ((u64)sqlite3Get4byte(p)<<32) | sqlite3Get4byte(p+4);
+#endif
+}
+
+/*
+** A specially optimized version of vdbeSorterCompare() that is used when
+** the SORTER_TYPE_REAL bit of VdbeSorter.typeMask proves that the first
+** field of every record added to the sorter is numeric (serial types 1
+** through 9) and at least one record has a REAL (serial type 7) first
+** field. REAL sort keys usually contain a mixture of serial type 7 and
+** integer serial types because REAL values with no fractional part are
+** stored as integers. Pairs of type-7 values are compared directly; any
+** pair involving an integer falls back to the generic comparator, as do
+** NaN payloads (which SQLite never generates, but might in theory arrive
+** from hostile inputs), so that no new comparison rule is introduced.
+*/
+static int vdbeSorterCompareReal(
+  SortSubtask *pTask,             /* Subtask context (for pKeyInfo) */
+  int *pbKey2Cached,              /* True if pTask->pUnpacked is pKey2 */
+  const void *pKey1, int nKey1,   /* Left side of comparison */
+  const void *pKey2, int nKey2    /* Right side of comparison */
+){
+  const u8 * const p1 = (const u8 * const)pKey1;
+  const u8 * const p2 = (const u8 * const)pKey2;
+  u64 x1;                               /* Big-endian bits of value 1 */
+  u64 x2;                               /* Big-endian bits of value 2 */
+  double r1;
+  double r2;
+  int res;
+
+  assert( p1[0]<0x80 && p2[0]<0x80 );  /* 1-byte headers: nAllField<13 */
+  assert( p1[1]>0 && p1[1]<10 );        /* first fields proven numeric */
+  assert( p2[1]>0 && p2[1]<10 );
+
+  if( p1[1]!=7 || p2[1]!=7 ){
+    /* One or both values are stored as INTEGER (this includes REAL values
+    ** with no fractional part - see the "intReal" record optimization).
+    ** Use the generic comparator for exact int/real comparison semantics. */
+    return vdbeSorterCompare(
+        pTask, pbKey2Cached, pKey1, nKey1, pKey2, nKey2
+    );
+  }
+  assert( p1[0]<=nKey1-8 && p2[0]<=nKey2-8 );
+
+  x1 = vdbeSorterGetRealBits(&p1[ p1[0] ]);
+  x2 = vdbeSorterGetRealBits(&p2[ p2[0] ]);
+  swapMixedEndianFloat(x1);
+  swapMixedEndianFloat(x2);
+  if( IsNaN(x1) || IsNaN(x2) ){
+    return vdbeSorterCompare(
+        pTask, pbKey2Cached, pKey1, nKey1, pKey2, nKey2
+    );
+  }
+  memcpy(&r1, &x1, sizeof(r1));
+  memcpy(&r2, &x2, sizeof(r2));
+  if( r1<r2 ){
+    res = -1;
+  }else if( r1>r2 ){
+    res = +1;
+  }else{
+    res = 0;
+  }
+
+  assert( pTask->pSorter->pKeyInfo->aSortFlags!=0 );
+  if( res==0 ){
+    if( pTask->pSorter->pKeyInfo->nKeyField>1 ){
+      res = vdbeSorterCompareTail(
+          pTask, pbKey2Cached, pKey1, nKey1, pKey2, nKey2
+      );
+    }
+  }else if( pTask->pSorter->pKeyInfo->aSortFlags[0] ){
+    assert( !(pTask->pSorter->pKeyInfo->aSortFlags[0]&KEYINFO_ORDER_BIGNULL) );
+    res = res * -1;
+  }
+
+  return res;
+}
+
