INSERT INTO t1(name,mode,mtime,data) VALUES('secret.txt', NULL, 1000, 'ROLLEDBACK_SECRET');
ROLLBACK;
-- run 2, fresh sqlite3 process, independent verification that the file on disk
-- still contains the row that was supposedly rolled back
CREATE VIRTUAL TABLE t2 USING zipfile('verify_rb.zip');
SELECT name,data FROM t2;

