# in the right-hand set.  SQLite's documented truth table (lang_expr.html, "The IN
# and NOT IN operators") says that when the left operand is not NULL, the right
# operand contains NULL and the left operand is not found, BOTH operators yield
# NULL.  The expectations below are those correct values, so these tests FAIL on
# an affected build.
set testdir [file normalize [file dirname $argv0]]
source $testdir/tester.tcl
set testprefix innull1

do_execsql_test 1.0 {
CREATE TABLE t2(y INT);
INSERT INTO t2 VALUES(10),(NULL);
SELECT 20 IN (SELECT y FROM t2), 20 NOT IN (SELECT y FROM t2);
} {{} {}}

do_execsql_test 1.1 {
CREATE INDEX i ON t2(y DESC);
SELECT 20 IN (SELECT y FROM t2), 20 NOT IN (SELECT y FROM t2);
} {{} {}}

# 2. The row-filtering consequence.
do_execsql_test 2.0 {
CREATE TABLE t1(b INT);
INSERT INTO t1 VALUES(20);
SELECT count(*) FROM t1 WHERE b NOT IN (SELECT y FROM t2);
} {0}

# 3. DELETE must not remove the row.
do_execsql_test 3.0 {
DELETE FROM t1 WHERE b NOT IN (SELECT y FROM t2);
SELECT count(*) FROM t1;
} {1}

# 4. TEXT values behave the same way.
do_execsql_test 4.0 {
CREATE TABLE t3(y TEXT);
INSERT INTO t3 VALUES('a'),(NULL);
CREATE INDEX i3 ON t3(y DESC);
SELECT 'z' IN (SELECT y FROM t3), 'z' NOT IN (SELECT y FROM t3);
} {{} {}}

# 5. Controls that are already correct: an ASC index, and defeating the index
#    with a unary "+".
do_execsql_test 5.0 {
CREATE TABLE t4(y INT);
INSERT INTO t4 VALUES(10),(NULL);
CREATE INDEX i4 ON t4(y ASC);
SELECT 20 IN (SELECT y FROM t4), 20 NOT IN (SELECT y FROM t4);
} {{} {}}
do_execsql_test 5.1 {
SELECT 20 IN (SELECT +y FROM t2), 20 NOT IN (SELECT +y FROM t2);
