Notably, VACCUM propagates it, and only REINDEX fixes it.

As per https://sqlite.org/autoinc.html for example:

You can access the ROWID of an SQLite table using one of the special column names ROWID, _ROWID_, or OID. Except if you declare an ordinary table column to use one of those special names, then the use of that name will refer to the declared column not to the internal ROWID.

SQL to show this, as well as TCL to test:
CREATE TABLE t(a INT, b INT);
INSERT INTO t VALUES(0,10),(0,20),(0,30);
CREATE INDEX i ON t(b) WHERE rowid > 1;
SELECT 'before (index)      = '||count(*) FROM (SELECT b FROM t WHERE rowid>1);

ALTER TABLE t RENAME COLUMN a TO rowid;

SELECT 'schema: '||sql FROM sqlite_schema ORDER BY rowid;
SELECT 'A  SELECT count(*) FROM t WHERE rowid>1              = '||count(*)
FROM (SELECT b FROM t WHERE rowid>1);
SELECT 'B  SELECT count(*) FROM t NOT INDEXED WHERE rowid>1  = '||count(*)
FROM (SELECT b FROM t NOT INDEXED WHERE rowid>1);
SELECT 'C  the a/rowid column really holds: '||group_concat(quote("rowid")) FROM t;
SELECT 'integrity_check: '||integrity_check FROM pragma_integrity_check;

CREATE TEMP TABLE r(k,v);
INSERT INTO r VALUES('A',(SELECT count(*) FROM (SELECT b FROM t WHERE rowid>1)));
INSERT INTO r VALUES('B',(SELECT count(*) FROM (SELECT b FROM t NOT INDEXED WHERE rowid>1)));
REINDEX;
INSERT INTO r VALUES('A2',(SELECT count(*) FROM (SELECT b FROM t WHERE rowid>1)));

SELECT CASE
WHEN (SELECT v FROM r WHERE k='A')=2 AND (SELECT v FROM r WHERE k='B')=0
AND (SELECT v FROM r WHERE k='A2')=0
THEN 'REPRODUCED  (partial index i is stale: 2 rows via the index, 0 by scan; '
||'REINDEX makes the index agree with the scan)'
WHEN (SELECT v FROM r WHERE k='A')=(SELECT v FROM r WHERE k='B')
THEN 'NOT reproduced (index and scan agree -- correct)'
ELSE 'INCONCLUSIVE'
END;

